s=importlib.util.spec_from_file_location('b',Path(__file__).with_name('continuous-warsaw-batch-000100.py'));b=importlib.util.module_from_spec(s);s.loader.exec_module(b);h=b.h;i=b.i
lock=(b.R/'worker.lock').open('a+');fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
observations={'460094': 'Original and derivative viewed. Seated Christ beside grape vine and chalice within an elaborate red and gilt architectural surround, paired columns and three putto heads. Full outside contours and grey photographic surround visible. Matches IK 159. Count the surviving inventoried icon with its frame once; uncertain former altar or iconostasis role retained.', '456544': 'Original and derivative viewed. Full rectangular canvas: seated Christ with cross at left, enthroned Father in priestly dress and globe at right, dove above and winged heads below. All supplied edges visible. Matches IK 158 and the source oil-on-canvas record; no current-display claim.', '498560': 'Original and derivative viewed. Complete panel with three standing saints, central figure holding a scroll and Christ above, gold field and red/green borders. All four board edges retained. Matches IK 322. Northern school authority remains a school label; its authority lifespan is not used as the artwork date.', '440236': 'Original and derivative viewed. Virgin in red maphorion holds seated Child with scroll and raised hand, gold ground, red outer edge and narrow grey surround. Complete board and proportions retained. Matches Greek-workshop IK 288; acquisition in 1964 is not its creation date.', '455229': 'Original and derivative viewed. Full worn rectangular panel, crowned Barbara holds sword and palm against blue-green background, ornate red lower cartouche. All irregular board edges visible. Matches IK 105. Historical deposit and uncertain donor wording remain in evidence; current holding rests on explicit owner field.', '498717': 'Original and derivative viewed. Complete open triptych with central enthroned Christ flanked by Virgin and John, smaller saints on stepped side wings. Hinges, all wing contours and grey surround preserved. One IK 90 object, not three works. Only interior primary view reviewed; exterior Annunciation remains an alternate-image gap. Source restoration of book retained.', '498514': 'Original and derivative viewed, plus prior native 498691 image for comparison. Frontal Anastasia holds a cross and open scroll inside a rich gold patterned frame with colored enamels. Full border visible. This IK 280 differs from IK 7, which has plain dark outer border, silver ground, a raised hand and prayer ladder. Distinct accession, composition and medium retained.', '498377': 'Original and derivative viewed. Full tall panel with curved interior arch and carved surround, central Michael with sword and Christ medallion among angels above clouds. All outer timber contours visible. Matches IK 155. One complete supplied surviving icon, not separate figures.', '498384': 'Original and derivative viewed. Small worn red/gold panel with tall central monk and two shorter princes, substantial edge loss and a hole near top right. Complete surviving irregular contour retained without reconstruction. Matches IK 164; uncertain Stroganov-school attribution stays qualified.', '499235': 'Original and derivative viewed. Red-faced Virgin in dark red garments against a gold field, small saints in narrow side borders and dark bands at top/bottom. All supplied board edges retained. Matches IK 426 with original circa 1850 wording. No new narrative text invented from the absent source description.'}
files=[];decisions=[]
for r in i.selected(b.B)['rows']:
 im=h.load(i.folder(b.B)/'prepared'/(r['artwork_id']+'.json'));assert im['state']=='prepared';raw=Path(im['path']).read_bytes();orig=Path(im['original_path']).read_bytes();assert h.sha(raw)==im['sha256'] and h.sha(orig)==im['source_sha256'] and len(raw)==im['bytes']<=100000
 with Image.open(io.BytesIO(raw)) as pic:pic.load();assert pic.format=='JPEG' and pic.size==(im['width'],im['height'])
 with Image.open(io.BytesIO(orig)) as pic:pic.load();assert abs(pic.width/pic.height-im['width']/im['height'])<.03
 assert '/Documents/' not in im['original_path']
 decisions.append(dict(artwork_id=r['artwork_id'],source_id=r['native_id'],artist=r['creator_label'],sha256=im['sha256'],decision='accept',viewed_individually=True,viewed_path=im['path'],viewed_original_path=im['original_path'],original_sha256=im['source_sha256'],original_viewed_individually=True,tool='functions tools.view_image',observations=observations[r['native_id']],flag_resolution='Original and actual derivative individually viewed. The manual_visual_required switch conservatively flags the 315-pixel museum derivative, but the actual image is a complete authentic icon, not a placeholder. Full supplied frame, native inventory and source description match; no unseen reverse or tiny-inscription claim.',identity_confidence=.99,confidence_basis='Exact native object/image, inventory, dimensions, source description and observed physical composition; editorial judgment, not calibrated probability.'))
 files.append(dict(artwork_id=r['artwork_id'],sha256=im['sha256'],bytes=im['bytes'],complete_decode=True,proportions_preserved=True,original_sha256=im['source_sha256'],original_path=im['original_path']))
assert len(decisions)==10
review=dict(at=h.now(),batch_quality_decision='accept',reviewer='Codex actual image viewing',decisions=decisions,all_selected_files_individually_viewed=True,sample_only_files=[],limitations='Museum source images are 315 px wide. Compositions and complete supplied frames reviewed; no claim to inspect absent reverse views or tiny illegible inscriptions. All ten originals and all ten derivatives individually visually viewed, decoded and hashed. Prior native 498691 derivative also viewed for same-subject version comparison.')
h.save(i.folder(b.B)/'visual-review.json',review);b.save('actual-visual-review.json',review);b.save('prewrite-file-verification.json',dict(at=h.now(),files=files,plan_sha256=h.pinned(b.PHASE)[1]))
print('10 actual per-image visual decisions and complete file checks saved')
